"Stripe の秘密鍵は sk_live_・sk_test_（または制限付きキーの rk_live_・rk_test_）で始まるものを入れてください。公開可能キー（pk_）ではありません。":"Enter a Stripe secret key starting with sk_live_ or sk_test_ (or rk_live_ / rk_test_ for restricted keys) — not a publishable key (pk_).",
"Stripe の秘密鍵はこのパソコンの中だけに置き、ホームページには渡しません（ホームページには決済ページのアドレスだけを送ります）。\n\tパソコンが止まっている間に売れた分は、次に起動したときに取り込みます。値段が 1 円単位でない・50 円未満の商品は対象外です（「申し込む」で受け付けます）。":"Your Stripe secret key stays only on this computer and is never given to your website (only the checkout page address is sent).\n\tSales made while this computer is off are imported the next time it starts. Products not priced in whole yen or under ¥50 are excluded (they are accepted with \"Apply\").",
"Stripe の管理画面「開発者」→「API キー」のシークレットキー。制限付きキーを使う場合は、Products・Prices・Payment Links・Subscriptions の書き込みと、Checkout Sessions・Invoices の読み取りを許可してください。":"The secret key from \"Developers\" → \"API keys\" in the Stripe Dashboard. If you use a restricted key, allow write access to Products, Prices, Payment Links and Subscriptions, and read access to Checkout Sessions and Invoices.",
