"iPad の「設定」→ 上に出る「プロファイルがダウンロードされました」→「インストール」。パスコードを聞かれたら入力します。":"On the iPad, open Settings → \"Profile Downloaded\" at the top → \"Install\". Enter your passcode if asked.",
"iPad のカメラで「① 証明書のプロファイル」の QR を読み取り、Safari で開きます。「構成プロファイルをダウンロードしますか？」に「許可」を選びます。":"Scan the \"① Certificate profile\" QR code with the iPad camera and open it in Safari. Choose \"Allow\" when asked to download a configuration profile.",
