"※ [ktpwp_public_products] のグリッド型・カード型一覧で、各商品カードの背景色を設定します。":"* Sets the background color of each product card in the grid and card layouts of [ktpwp_public_products].",
"※ 「ボツ」案件は売上計算から除外されています。":"Rejected orders are excluded from sales calculations.",
"※ 「一律税率」を選択すると入力した税率が全明細に適用され、行ごとの税率編集はできません。「消費税なし」を選択すると税率/税額列は非表示になります。":"When \"Uniform tax rate\" is selected, the entered rate applies to all line items and line-specific tax rates cannot be edited. When \"No consumption tax\" is selected, tax rate and tax amount columns are hidden.",
"※ ここでチェックした言語以外で書かれたお問い合わせフォームからの送信は、受注として取り込まずスパム対策として拒否します（本文の文字種による簡易判定です）。何も選択しない場合は日本語のみが許可されます。":"* Inquiry form submissions written in languages other than those checked here are rejected as spam instead of being imported as orders (a simple check based on the characters in the message). If nothing is selected, only Japanese is allowed.",
"※ このメールは自動送信されています。":"This email was sent automatically.",
"※ この設定は「一律税率」モード選択時のみ有効です。未入力時は既定の5%が適用されます。0を入力した場合は0%で固定されます。":"This setting is only active in Uniform tax rate mode. If left blank, the default 5% is applied. Enter 0 to fix the rate at 0%.",
"※ アクティブなタブの背景色を設定してください。":"Set the active tab background color.",
"※ サイトから届くメールが迷惑メールと認識されないよう、サイトのドメインと同じメールアドレスをご入力ください。":"To prevent site emails from being marked as spam, enter an email address using the same domain as the site.",
"※ システムの説明は固定です（変更できません）。":"The system description is fixed and cannot be changed.",
"※ システム名は固定です（変更できません）。":"The system name is fixed and cannot be changed.",
"※ タブの下線（border-bottom）の色を設定してください。":"Set the tab underline (border-bottom) color.",
"※ プラグインに適用するカスタムCSSを記述してください。HTMLタグは使用できません。":"Enter custom CSS to apply to the plugin. HTML tags cannot be used.",
"※ ヘッダーの背景画像として使用されます。推奨サイズ: 1920×100px":"Used as the header background image. Recommended size: 1920 x 100px",
"※ ボディ背景画像の見え方です。「くっきり」ほど画像がはっきり見えます。":"* How visible the body background image is. The closer to \"Clear\", the sharper the image.",
"※ メール送信時に署名として使用される会社情報です。HTMLタグが使用できます。":"Company information used as the signature when sending email. HTML tags can be used.",
"※ リストで一度に表示する件数を設定してください。":"Set the number of items shown at once in lists.",
"※ リスト表示で偶数行（2行目、4行目など）の背景色を設定してください。":"Set the background color for even rows in list views.",
"※ リスト表示で奇数行（1行目、3行目など）の背景色を設定してください。":"Set the background color for odd rows in list views.",
"※ ロゴマークは固定です（変更できません）。":"The logo is fixed and cannot be changed.",
"※ 入力してください":"Please enter",
"※ 全%1$d件中、最新10件を表示。全件は印刷プレビューでご確認ください。":"Showing the latest 10 of %1$d items. View all items in print preview.",
"※ 期間集計は受付日ではなく、完了日を基準にしています。":"Period totals are based on completion date, not received date.",
"※ 本画面の印刷位置は、プリンタの印刷余白が上下左右いずれも10mmのときに長形３号窓明封筒の窓と揃うようレイアウトしています。":"Print positions on this screen align with a long No. 3 window envelope when printer margins are 10 mm on all sides.",
"※ 画面全体の背景に敷く画像です。顧客リスト・顧客の詳細などの欄はすりガラスのように透けて、画像がうっすら見えます。横長の写真（1920×1080px くらい）がおすすめです。":"* An image laid behind the whole screen. Panels such as the customer list and details become frosted glass, so the image shows through faintly. A landscape photo (about 1920×1080 px) is recommended.",
"※ 税の名前、登録番号の欄、支払条件（日本は締め日・支払日、ほかの国は Net 日数）、印鑑・FAX の表示が、この国の商取引に合わせて変わります。":"* The tax name, the tax registration number field, payment terms (closing day and payment day in Japan, Net days elsewhere), and the company seal and fax features follow the business rules of this country.",
"※ 納期警告日数を設定してください。":"Set the delivery warning days.",
"※ 請求項目があっても進捗が「完了」以前の場合は売上に含まれません。":"Orders before Completed are not included in sales even if they have invoice items.",
"※ 適格請求書発行事業者の登録番号を入力してください。（例：T1234567890123）":"Enter the qualified invoice issuer registration number. Example: T1234567890123",
"※ 金額の表示通貨です。為替換算は行わず、入力済みの数値を選択した通貨として表示します。":"Display currency for amounts. Exchange conversion is not performed; entered numeric values are shown as the selected currency.",
"※ 長形３号窓明封筒の窓と揃うようレイアウトしています。「印刷」と「PDFを保存」は同じ内容（各ページ10mm余白・同一の改ページ）です。プリンタの余白は「なし」（最小）に設定してください。iPad・スマートフォンでは「印刷」もプレビューと同じPDFの保存／共有になります。":"※ Layout aligns with a long No. 3 window envelope. Print and Save PDF use the same output (10 mm margins on every page, identical page breaks). Set printer margins to none (minimum). On iPad and smartphones, Print also saves/shares the same preview PDF.",
"※ 長形３号窓明封筒の窓と揃うようレイアウトしています。「印刷」はプレビューと同じ内容（A4・10mm余白）です。プリンタの余白は「なし」（最小）に設定してください。iPad・iPhoneでは「印刷」もプレビューと同じPDFの保存／共有になります。":"※ Layout aligns with a long No. 3 window envelope. Print matches the preview (A4, 10 mm margins). Set printer margins to none (minimum). On iPad and iPhone, Print saves/shares the same preview PDF.",
"※ 非アクティブなタブの背景色を設定してください。":"Set the inactive tab background color.",
"※「画像を削除」で画像なしの白い背景になります（アップロードした画像はメディアに残ります）。どのボタンも、押したあと「設定を保存」で反映されます。":"* \"Remove image\" gives a plain white background (uploaded images remain in the media library). Changes from any button take effect after \"Save Settings\".",
