"「② アプリを開く」の QR を読み取ります。ログイン画面が警告なしで開きます。Safari の共有ボタン →「ホーム画面に追加」で、アプリのように使えます。":"Scan the \"② Open the app\" QR code. The login screen opens without a warning. Use Safari's Share button → \"Add to Home Screen\" to use it like an app.",
"「へいカンタンプロ、今月の売上は」のように、話しかけて売上や予定を調べられます（KoeType 連携）。":"Check sales and schedules by speaking, e.g. \"Hey KantanPro, this month's sales\" (KoeType integration, Japanese).",
"「アカウントを完全削除」は開発者のみが実行できます。他オフィスに参加していない場合のみ削除可能です。削除後は同じメールでも新規アカウントとして登録し直すことになります。":"\"Delete account permanently\" can be executed by developers only. Deletion is possible only when the user is not in other offices. After deletion, even the same email must re-register as a new account.",
"「サイトから受注を取り込む」がオフです。":"\"Import orders from the website\" is off.",
"「サイト公開」にした商品がまだありません。":"No products are marked \"Published\" yet.",
"「サイト公開」にした商品を、ホームページに載せる":"Show products marked \"Published\" on your website",
"「スタッフ管理」":"\"Staff Management\"",
"「データは完全に削除する」を選んだ場合でも、削除が実行されるタイミングは、解約の効力が発生する瞬間と必ずしも同時ではありません。手順・条件は利用規約および画面の案内に従ってください。":"Even if \"Delete all data\" is selected, data deletion timing does not necessarily match the exact moment cancellation takes effect. Follow the Terms and on-screen guidance.",
"「トークンの名前」に用途が分かる名前を入力（例：iPhone、経理連携）":"Enter a recognizable name under “Token name” (e.g. iPhone, Accounting sync)",
"「トークンを発行」を押す":"Click “Issue token”",
"「メモを保存する」がオンのとき、罫線エリアのメモは次回この宛名印刷を開くまで保存されます。":"When Save memo is on, notes in the ruled area are kept until you open this addressee print page again.",
"「一律税率」モードのときに明細へ適用されます（既定 5%）。":"Applied to line items in \"Unified tax rate\" mode (default 5%).",
"「安全ではありません」などの警告が出ます（この PC が自分で作った証明書のためです）。「詳細」→「このまま進む（アクセスする）」を選びます。最初の 1 回だけです。警告を出したくないときは、":"A warning such as \"Not secure\" appears (because this PC created its own certificate). Choose \"Advanced\" → \"Proceed\". This is only needed the first time. To avoid the warning, append",
"「完全削除」を選んだ状態でプラグインを削除すると、すべてのデータが失われ、元に戻せません。必ず事前にバックアップを取ってから実行してください。":"If you delete the plugin with Full delete selected, all data will be lost and cannot be restored. Always back up before proceeding.",
"「既存データを全て削除してインポートする」を選ぶと、業務データを入れ替えて取り込みます":"Choosing replace clears existing data and imports fresh business data",
"「既存データを残して追加でインポートする」を選ぶと、現在データは残したまま取り込みます":"Choosing append keeps existing data and adds imported data",
"「設定」→「KantanProEX 受付」を開くと、サイトのアドレスと接続キーが出ます。":"Open \"Settings\" → \"KantanProEX Intake\" on your website to see the site address and connection key.",
"「設定」→「一般」→「情報」→ 一番下の「証明書信頼設定」で、「KantanProEX LAN 認証局」をオンにします（ここを忘れると警告が出続けます）。":"In Settings → General → About → \"Certificate Trust Settings\" at the bottom, turn on \"KantanProEX LAN 認証局\" (if you skip this, the warning keeps appearing).",
"「請求書在中」を含む宛名ブロックだけを動かせます（明細行など本文の幅・位置は変わりません）。窓付き封筒の窓に合わせて調整してください。一括請求書プレビュー画面で宛名ブロックを直接ドラッグして動かすこともできます。":"Moves only the address block (including \"Invoice Enclosed\"). The width/position of the body content (line items, etc.) is unaffected. Adjust to align with your window envelope. You can also drag the address block directly on the bulk invoice preview.",
