"お使いのホームページ（WordPress）の Contact Form 7 のお問い合わせと WooCommerce の注文を、このアプリの受注として取り込みます。ホームページに受付用のプラグインを入れておくと、そこに預けられた分を、このアプリが 15 分ごと（と起動したとき）に取りに行きます。「サイト公開」にした商品も、このアプリからホームページへ送って表示できます。この PC をインターネットに公開することはありません。":"Imports Contact Form 7 inquiries and WooCommerce orders from your website (WordPress) as orders in this app. With the intake plugin installed on your website, this app collects what has been left there every 15 minutes (and at startup). Products marked \"Published\" can also be sent from this app to your website. This PC is never exposed to the internet.",
