"お知らせの投稿は、この開発者ダッシュボード（下のフォーム）からのみ行えます。公開後、各オフィスの参加ユーザーは画面上部メニューバーのベルで確認でき、未読のときだけ赤いバッジが付きます。あわせて各オフィスのオーナー（メール認証済み）にも通知メールを送信します。本文に https:// の URL を書くとクリック可能なリンクになります。":"Post announcements only from this developer dashboard (form below). After publishing, participating users in each office see them from the bell in the top menu bar; a red badge appears only while unread. Verified office owners also receive an email notification. URLs starting with https:// in the body become clickable links.",
