"この PC（親機）にあるデータを、同じ事務所のネットワーク（LAN）につながった他の PC のブラウザから、スタッフが使えるようにします。データは親機の中にだけあり、インターネット上には置きません。":"Lets staff use the data on this PC (the host) from a browser on other PCs connected to the same office network (LAN). The data stays only on the host and is never placed on the internet.",
