"このスタッフのログインアカウントをデータベースから完全に削除します。\n\n他のオフィスに所属中の場合は削除できません。\n削除後、同じメールアドレスで登録し直す場合は別アカウント扱いになります。\n\n本当に削除しますか？":"This will permanently delete this staff member's login account from the database.\n\nIf they belong to another office, deletion is not possible.\nAfter deletion, re-registering with the same email is treated as a different account.\n\nDelete permanently?",
