"オンにすると、オーナー（管理者）も他の端末からログインできます。業務の画面（受注・顧客・レポートなど）だけが使え、設定・LAN 共有の設定・バックアップ・取り込みは、この PC の画面でだけ操作できます。スタッフより長い":"When on, the owner (administrator) can also sign in from other devices. Only the business screens (orders, customers, reports, etc.) are available there; settings, LAN sharing settings, backups and imports can only be used on this PC. Choose a dedicated password of at least",
"オンにすると、オーナー（管理者）も他の端末からログインできます。業務の画面（受注・顧客・レポートなど）だけが使え、設定・LAN 共有の設定・バックアップ・取り込みは、この PC の画面でだけ操作できます。スタッフより長い 12 文字以上の、専用のパスワードを決めてください。":"When on, the owner (administrator) can also sign in from other devices. Only the business screens (orders, customers, reports, etc.) are available there; settings, LAN sharing settings, backups and imports can only be used on this PC. Choose a dedicated password of at least 12 characters, longer than staff passwords.",
"オンにすると、受注書の入力画面を出さずにすぐ受注書を作成し、詳細画面を開きます。案件名は「※ 入力してください」で作成され、部署は顧客で選択中の部署になります。オフ（初期値）のときは、これまでどおり入力画面が開きます。":"When on, \"Create order\" on the client screen creates the order immediately and opens its detail page. The title is set to a placeholder and the department is the client's selected department. When off (default), the input screen opens as before.",
"オンにすると、次回この宛名印刷を開いたときにメモを復元します。":"When enabled, your memo is restored the next time you open this addressee print page.",
