"オーナーのみ設定できます。受注の作成・更新・削除に加え、請求明細の変更後（売上合計の同期後）と原価明細の変更後にも order.updated が送られます。作成・削除は order.created / order.deleted。テスト送信は webhook.ping（署名付き・即時実行）。":"Only owners can configure this. Besides order create/update/delete, order.updated is also sent after invoice-line changes (after sales total sync) and cost-line changes. order.created / order.deleted are sent on create/delete. Test send uses webhook.ping (signed, immediate).",
