"チェックすると、ホームページのボタンが「購入する」になり、Stripe の決済ページでそのままカード払いできます。入金されると受注（入金済み）で入ります。":"When checked, the button on your website becomes \"Buy\" and customers can pay by card on the Stripe checkout page. Once paid, it comes in as an order (Paid).",
"チェックすると税率欄が読み取り専用になります（一律・消費税なしモードでは常に固定）。":"When checked, tax rate fields become read-only (always fixed in unified/no-tax mode).",
"チェックを付けると、一括請求書のあとに対象案件の納品書を続けて出力します（印刷・PDF保存の両方）。":"When checked, delivery notes for each included order are appended after the bulk invoice (for both Print and Save PDF).",
