"テスト配信に失敗しました。laravel.log の Webhook delivery exception（url フィールド）を確認してください。php artisan serve 向けは http:// の URL に保存してください。SaaS と受信アプリで同じポートを使うと競合するため、受信側は別ポートにしてください。":"Test delivery failed. Check the Webhook delivery exception in laravel.log (url field). For php artisan serve, save an http:// URL. Use a different port for the receiving app because SaaS and receiver apps conflict on the same port.",
"テスト配信に失敗しました。storage/logs/laravel.log の「Webhook delivery exception」を確認してください（url フィールドに実際に POST した URL が出ます）。 php artisan serve は HTTP のみのため、受信 URL は http://127.0.0.1:... のように http にし、Webhook を編集して保存したうえで再試行してください（https のままだと TLS でタイムアウトしやすいです）。 受信側のサーバーが起動しているか、POST 用のパスが正しいか確認してください。SaaS と受信アプリの両方を同じポート（例: 8000）で動かそうとするとどちらか一方しか起動できないため、受信側は別ポート（例: php artisan serve --port=8001）にするとよいです。":"Test delivery failed. Check \"Webhook delivery exception\" in storage/logs/laravel.log (actual POST URL is shown in url field). Since php artisan serve supports HTTP only, use an http receiver URL like http://127.0.0.1:... , save webhook changes, then retry (https can timeout on TLS). Confirm receiver server is running and POST path is correct. If SaaS and receiver app try to run on the same port (e.g. 8000), only one can run; use a different port for receiver (e.g. php artisan serve --port=8001).",
