"プラグインをアンインストール（削除）する時に、登録されたデータをどう扱うかを選択できます。":"Choose how registered data is handled when uninstalling (deleting) the plugin.",
"プラグインを削除しても、顧客・サービス・協力会社・受注書などのデータはデータベースに残ります。後からプラグインを再インストールしたとき、以前のデータをそのまま引き続き利用できます。":"Even if the plugin is deleted, customer, service, supplier, order and other data remains in the database. If the plugin is reinstalled later, the previous data can be used as is.",
"プラグインを削除すると同時に、KantanProに保存されている全データ（顧客・サービス・協力会社・受注書・請求書・設定など）をデータベースから完全に削除します。":"When the plugin is deleted, all data stored by KantanPro (customers, services, suppliers, orders, invoices, settings, etc.) is completely removed from the database.",
