"ホームページから受注が %d 件届きました。":"%d orders arrived from your website.",
"ホームページのお問い合わせ（Contact Form 7）や WooCommerce の注文を 15 分ごとに自動で受注に取り込みます。Stripe のカード払いも、入金済みの受注として入ります。":"Automatically imports website inquiries (Contact Form 7) and WooCommerce orders as orders every 15 minutes. Stripe card payments also come in as paid orders.",
"ホームページの商品ごとのページです。SNS・ブログ・LINE・メールに貼ると、商品名と画像のカードで表示されます（新しく公開した商品は、ホームページに反映されてから開けます）。":"A page for each product on your website. When pasted into social media, blogs, LINE or email, it shows as a card with the product name and image (newly published products open after they reach your website).",
"ホームページの商品は「申し込む」ボタンで受け付けます（受注が受付中で入り、あとから請求します）。その場でカード払いにするには、KantanProEX 設定 →「サイトからの受注」で Stripe の秘密鍵を入れてください。":"Products on your website are accepted with an \"Apply\" button (the order comes in as Received and you invoice later). To take card payments on the spot, enter your Stripe secret key in KantanProEX Settings → \"Orders from Your Website\".",
"ホームページの固定ページ（または投稿）に、次のように書きます。「サイト公開」にした商品が、カードで並びます。":"Add the following to a page (or post) on your website. Products marked \"Published\" are shown as cards.",
"ホームページの管理画面で「プラグイン」→「新規プラグインを追加」→「プラグインのアップロード」から ZIP を選び、有効にします。":"In your website's admin, go to \"Plugins\" → \"Add New Plugin\" → \"Upload Plugin\", choose the ZIP, and activate it.",
"ホームページは https で開けるものに限ります。WordPress 版の KantanPro / KantanProEX を同じホームページで使っている場合は、二重に受注ができないよう、そちらの Contact Form 7・WooCommerce 連携を止めてください。":"Your website must open over https. If you also use the WordPress edition of KantanPro / KantanProEX on the same website, turn off its Contact Form 7 and WooCommerce integration to avoid duplicate orders.",
