"ライトモード用とダークモード用をそれぞれ設定できます。開発者向けのためアプリ側のファイルサイズ上限はありません。画像を選んで保存すると、ブラウザが自動的に Base64 で送信し、PHP の upload_max_filesize（多くは 2MB）による失敗を避けます（全体サイズは post_max_size 等の制限の対象です）。モードごとに「保存」してください。":"You can set separate images for light mode and dark mode. For developer tools, there is no app-side file size limit. On save, the browser sends Base64 automatically to avoid failures from PHP upload_max_filesize (often 2MB). Total payload is still limited by post_max_size and others. Save each mode separately.",
