"添付画像・PDF: 通常は別の WordPress サイトの Contact Form 7 から Webhook で送ります（「CF7 to Webhook」等）。Files の「Send content」は ON（中身を送信）が確実です。OFF の場合は、そのサイト上の公開 URL を KantanBiz が取得して案件ファイルに保存します。対応形式は PDF・JPEG・PNG・GIF・WebP（最大 20MB・10 件）。同一ドメインでのテストも可能です。":"Attachments: Normally CF7 runs on a separate WordPress site and posts via a webhook plugin (e.g. CF7 to Webhook). Prefer Send content ON (file bytes). With OFF, KantanBiz downloads the public file URL from that site into Project files. Allowed: PDF, JPEG, PNG, GIF, WebP (max 20MB, up to 10). Same-domain setups work for testing.",
